Section LinDenot.
Variable E : env.
Definition uE (e : expr) : Z := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S00$e;R+P!2'^H!1,^C|600;!2'`S/E;#1").

Fixpoint tden (ts : list (Z * expr)) : Z :=
  match ts with [] => 0 | (k, a) :: rest => k * uE a + tden rest end.
