Fixpoint mem_denot (E : env) (base : word -> option byte) (log : list sentry)
  : word -> option byte :=
  match log with
  | [] => base
  | SE a w v :: rest =>
      wbytes (mem_denot E base rest) (adenot E a) (word_to_le_bytes w (edenot E v))
  end.

Lemma mem_denot_grows : forall E base log, mem_grows base (mem_denot E base log).
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S50|30;!1+_5+f8!3'f:#<#;#2!2'f>#<#5!2'f?#4!2'`S#<#3$E;R+^A$base;R%~R!1+^B!1,^C|600;!1+bI!1+^B!1,^C0$log;R1!5'`X+f8$log;R1!2'f9#3!3'f:#4#3#1vd!1'f;#2!2'f9#2!3'f:#3#2!1,_3+f8$a0;R+f8-f8RN$s;R+f8%l;R1%~R!2'f9#5!3'f:#6#5#1!2'f9#6!3'f:#7#6!3,_L+f8#3#2#11$e_addr;R+^=$e_width;R+Y$e_val;R+P!3$a;R+^=$w;R+Y$v;R+P$rest;R1$IH;R!2'f9#:!3'f:#;#:#1vd!5'f<#;2!3'f=234#1!3'f@423!2'f9#;!3'f:#<#;!3,_L+f8!3,fA#5#4#3#2#3#2#1#1").
Qed.

Definition estart (E : env) (a : saddr) : Z := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S00$E;R+^A$a;R+^=!2'^J!2'^H!1,^C|600;!2'`S#2!1'fB#1!1'fC#1").
Definition elenZ (E : env) (n : expr) : Z := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S00$E;R+^A$n;R+P!2'^H!1,^C|600;!2'`S#2#1").

