Lemma u_lit64 : forall z, bv_unsigned (Z_to_bv 64 z) = (z mod two64)%Z.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S50|600;!1,^C0!2'^K1#1$z;R+S!3+1+S#1!2'`=#2'd@|10;$z;R+S!6'X+S23!6'X+S!2'`=#1!2'^Z!1,^[4!1,^[03!2,6+S!2'`=#1'd@2!1'`P#1!2'^H1!2'^D1#1!2'^N1#1").
Qed.

Lemma two64_eq : two64 = (2 ^ 64)%Z.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S10|10;!2,6+S!2'^Z!1,^[0!1,^[|600;").
Qed.

Lemma u_add64 : forall x y : word,
  bv_unsigned (alu64 ALU_ADD x y) = ((bv_unsigned x + bv_unsigned y) mod 2 ^ 64)%Z.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S90|600;!1,^C0!1+^B1!2'^E#2#1!2'^H1#1!2'^H1#2|10;!2'^Z!1,^[6!1,^[0!2'^J54$x;R2$y;R2!6'X23$b;R2!3+1+S4!2'`=!2'^J!2'^H1#357vd!1'i78!3+1+S!2'^H13!2'`=87!3'^O,5#2#1!2'^P#2#1").
Qed.

Lemma u_sub64 : forall x y : word,
  bv_unsigned (alu64 ALU_SUB x y) = ((bv_unsigned x - bv_unsigned y) mod 2 ^ 64)%Z.
