Lemma u_lit0 : bv_unsigned (Z_to_bv 64 0) = 0%Z.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!2,6+S,^F").
Qed.

Lemma estart_lit0 : forall E rk, estart E (SA (ELit 0) rk) = rk.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S40!1+_9+S!2,_>+S,_?!1,^C|600;!2,^?!1,T,^F#1$E;R+^A$rk;R+Svdvd!6'X+S,^F$z;R+S!3+1+S!2'^J#1#2#2&__arith;R$__x1;R+S&__wit;R!1,_3+_4!1+_5+_4&__varmap;R!2,_6+S#2!1+_7+S&__ff;R!7,_80'_:+_;+_;,_<!4,_=+S!3,_A+S!2,_C+S,^F1,_@1,_E!2'_F0,_<!4'_G#1#3vv!2,6+2,4!3+1+2!2'_H#1#3,4!3'_I+S,^F#2%__x1;R+S!3+1+S!2'^J,^F#1#1!1#1#2!2'^H2!2'^D2,^F'qT!3+1+S!2'^J!2'^H2!2'`S#2!1'fB3!1'fC3#1!3+1+S!2'fD#23#1").
