Lemma sym_step_sound : forall E base rom ss ms i ss' scs scr scr' w,
  fetch_word segs (Z_to_bv 64 (s_pc ss)) = Some w ->
  is_ecall w = false ->
  decode_any w = Some (i, 4%Z) ->
  sym_step segs i (clr ss) scr = SOk ss' scs scr' ->
  scs_denot segs base E scs ->
  st_ok E base rom ss ms ->
  exists ms', RiscvSemantics.step segs ms = MachineOk ms'
              /\ st_okR E base rom ss' ms'.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S70!1,^C|600;|30;%~R!1+^B0!1+bI!1+^B!1,^C1|500;!1+^B!1,^C3!2+_Z+^`?+S|20;$E;R+^A$base;R2$rom;R2$ss;R+^^Q$ms;R+^^R$i;R+^`?$ss';R+^^Q$scs;R!1+_5+fJ$scr;R+^_>$scr';R+^_>$w;R4$Hf;R!3+1!1+bI4!2'^`=/segs;!2'^D0!1'^^V#8!2,bK4#1$He;R!3+1+2!1'^`>#2,7$Hd;R!3+1!1+bI5!1'^`@#3!2,bK5!4,`\+^`?+S#8!1,^[6$Hs;R!3+1+^`B!4'^`C/segs;#9!1'^^[#;#6!3,^`D#8#7#5$Hsc;R!4'h?/segs;#>#?#8$Hst;R!5'^^S#@#?#>#=#<!A'^bY#A#@#?!1'^^[#>#=#<#;#:#9#8#7#6#5#4#3#2!6'^bZ#A#@#?#>#=#1").
Qed.

