(* [comment removed for export] *)
Lemma sym_execT_go_sound : forall t fuel first stops ss ck E base rom,
  itab_sound segs t ->
  sym_execT_go segs t fuel first stops ss ck = ck \/
  (let r := sym_execT_go segs t fuel first stops ss ck in
