Lemma wbytes_out : forall bs m (a x : word),
  (bv_unsigned a + Z.of_nat (length bs) <= 2 ^ 64)%Z ->
  (bv_unsigned x < bv_unsigned a \/ bv_unsigned a + Z.of_nat (length bs) <= bv_unsigned x)%Z ->
  wbytes m a bs x = m x.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S=0|30;!1+^B!1,^C0|600;!1,^C2!1+^B3!1+bI1!2'^H3#2|10;!2'^H3#3!2'^H3#4!2'_089!2'_1!2'^J9!1'cR!2'g91#68!2'^H3#5$bs;R!1+_51$m;R%~R45$a;R4$x;R4$Hnw;R!2'_1!2'^J6!1'cR!2'g91#4!2'^Z!1,^[7!1,^[2$H0;R!2+c0!2'_068!2'_1!2'^J8!1'cR!2'g91#56!6'c1:;!3+15!4'f=#5#4#6#3!1#5#3$~R:!1$H;R!2'_09<!6'^e:#8#7#6#5#4#1#1$~R;!1$H;R!2'_1!2'^J<!1'cR!2'g91#79!5'^e;#8#7#6#5#1#1#1").
Qed.

Section CarrySound.
Variable segs : list Segment.
Variable scfg : SpuriousCfg.

(* [comment removed for export] *)
Lemma kentry_ok_frame : forall E M (wa : saddr) w (V : word) K (ka : saddr) (kl : expr),
  flat E wa (Z.of_nat w) ->
  kentry_ok segs E M K ->
  match K with
  | KWord a w' _ => ka = a /\ kl = elen w' /\ (w' <= 8)%nat
  | KZero a n => ka = a /\ kl = n
  | KBlob a n _ => ka = a /\ kl = n
  | KImg lo hi => ka = SA (ELit 0) lo /\ kl = ELit (hi - lo) /\ (hi - lo < 2 ^ 64)%Z
  | KAlign _ _ => True
  | KRange _ _ _ => True
  | KWr _ _ => True
  | KDisj _ _ _ _ => True
  | KFill a n _ => ka = a /\ kl = n
  | KUnk a n => ka = a /\ kl = n
  end ->
