Lemma Forall_app_intro : forall {A} (P : A -> Prop) l1 l2,
  Forall P l1 -> Forall P l2 -> Forall P (l1 ++ l2).
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S74lcd;gh@d;lcd;ghAd;lcd;gfHd;<scd;%~R#1w!1+_5#2!1+_5#3!3+fH#4#3#2!3+fH#5#4#2%~R!3+fH#4#3!3'hA#4#2#1!2+^8!3+fH#5#4#34%~R!2+^83!3+fH#4#3#1!3+fH#5#4!3'hA#5#3#2$A;R{cd;$P;R0$l1;R1$l2;R2$~R3$~R4&H1;R$A;R{gh@d;$P;R0$l1;R1$l2;R2!5'V56%~R!2+^8!3+fH#4#3#2!3+fH#4#3#1!3+fH#5#4!3'hA#5#3#2$~R5$~R%~R!2+^8!3+fH#5#4#3!3+fH#5#4#2!3+fH#6#5!3'hA#6#4#3#1!4'h@#4#3#2#1%A;R{gh@d;%P;R0%l1;R1%l2;R26!5#1#7#6#5#4!4,bQ!3+fH#7#6#5!3+fH#7#6#4#3#2").
Qed.


Lemma kzero_piece : forall E M (wb : expr) (wk : Z) w (V : word) (kk l0 i0 len : Z),
  flat E (SA wb wk) (Z.of_nat w) ->
  kentry_ok segs E M (KZero (SA wb kk) (ELit l0)) ->
  (0 <= i0)%Z -> (0 < len)%Z -> (i0 + len <= l0 mod 2 ^ 64)%Z ->
  ((kk + i0 + len <= wk)%Z \/ (wk + Z.of_nat w <= kk + i0)%Z) ->
