(* [comment removed for export] *)
Lemma know_ok_fill_intro_pt : forall E M (a : saddr) (n : expr) c,
  flat E a (elenZ E n) ->
  (forall i, (0 <= i < elenZ E n)%Z -> M (Z_to_bv 64 (estart E a + i)) = Some (Z_to_bv 8 c)) ->
  kentry_ok segs E M (KFill a n c).
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S70!1,^C|600;|30;!1,^C1!1+^B2!1+bI3!2'_1,^F#1!2'fQ#7#4$E;R+^A$M;R%x;R!1+^B04$a;R+^=$n;R+P$c;R+S$Hfl;R!3'fE#5#3!2'fQ#5#2$Hc;R%i;R+S%~R!2+^85!2'_0#16!3+14!1#7!2'^D0!2'^J!2'fD#8#6#2!2,bK3!2'^D2#4vd!4,bQ!3'fE#7#56%i;R+S%~R!2+^85!2'_0#1!2'fQ#8#5!3+14!1#8!2'^D0!2'^J!2'fD#9#7#2!2,bK3!2'^D2#5#2#1!4'fI/segs;#7#6!3,i5#5#4#3").
Qed.

(* [comment removed for export] *)
Lemma know_ok_fill_intro : forall E M (a : saddr) (n : nat) (ne : expr) c,
  flat E a (Z.of_nat n) -> elenZ E ne = Z.of_nat n ->
